 // Per-column sum: walk row by row so the inner loop is contiguous in
 // memory. Each access is data_[r * cols_ + c] for consecutive c, which
 // is the stride-1 pattern that fits in L1. The previous column-major
 // version stepped by `cols_` doubles per access, blowing the cache on
 // anything larger than ~256x256.
 std::vector<double> Matrix::SumPerColumn() const {
     std::vector<double> result(cols_, 0.0);
     for (std::size_t r = 0; r < rows_; ++r) {
         const std::size_t base = r * cols_;
         for (std::size_t c = 0; c < cols_; ++c) {
             result[c] += data_[base + c];
         }
     }
     return result;
 }
